#!/usr/bin/env python3
"""Bounded production UI proposal. All routes use keyed resources and fail closed."""
import pathlib,subprocess,xml.etree.ElementTree as ET,re,time,json,hashlib
R=pathlib.Path.cwd();OUT=R/'evidence';OUT.mkdir(exist_ok=True);PKG='app.spool.music';NAME='Upgrade59Local';LOCALE='en';SHOTS=[];PAGE=();STRINGS={}
def adb(*a):return subprocess.check_output(['adb',*map(str,a)],stderr=subprocess.STDOUT,timeout=45)
def load():
 for lang,folder in [('en','values'),('ml','values-ml')]:
  for bundle,path in [('app','app/src/main/res'),('shared','sharedUi/src/commonMain/composeResources')]:
   STRINGS[lang,bundle]={n.get('name'):''.join(n.itertext()).replace("\\'", "'") for n in ET.parse(R/'archive-tree'/path/folder/'strings.xml').getroot().findall('string')}
def res(key,bundle='app'):return STRINGS[LOCALE,bundle][key]
def txt(key,bundle='app'):return ('resource',bundle,key)
def desc(key,bundle='app'):return ('description',bundle,key)
def text(key,bundle='app'):return ('text',bundle,key)
def quick(key):return ('quick','shared',key)
def literal(text):return ('literal',text)
def value(ref):return res(ref[2],ref[1]) if ref[0] in {'resource','description','text','quick','language-option'} else ref[1]
COMPONENT=PKG+'/com.music.bitchord.MainActivity'
ALIAS_COMPONENT=PKG+'/com.music.bitchord.LauncherSpool'
RUNTIME_COMPONENT=None
def parse_focus(s):
 focus=re.findall(r'^\s*mCurrentFocus=Window\{[^}]*\su\d+ ([^\s}]+)',s,re.M)
 assert len(focus)==1 and focus[0]==RUNTIME_COMPONENT,('Wrong current component',focus)
 return focus[0]
def parse_resumed(s):
 # Exact fields observed in this API34 image, both must identify same component.
 resumed=re.findall(r'^\s*ResumedActivity:\s*ActivityRecord\{[^}]*\su\d+ ([^\s}]+)',s,re.M)
 top=re.findall(r'^\s*topResumedActivity=ActivityRecord\{[^}]*\su\d+ ([^\s}]+)',s,re.M)
 assert len(resumed)==1 and len(top)==1 and resumed[0]==top[0]==RUNTIME_COMPONENT,('Wrong or ambiguous resumed component',resumed,top)
 return resumed[0]
def window():
 focus=parse_focus(adb('shell','dumpsys','window').decode())
 assert parse_resumed(adb('shell','dumpsys','activity','activities').decode())==focus
 return focus
def owned_xml(raw):
 tree=ET.fromstring(raw[raw.index(b'<?xml'):])
 pkgs={n.get('package') for n in tree.iter('node') if n.get('package')}
 assert PKG in pkgs and pkgs <= {PKG,'com.android.systemui'},('Foreign accessibility package',pkgs)
 return tree
def snapshot():
 win=window();adb('shell','uiautomator','dump','/sdcard/spool-window.xml');raw=adb('exec-out','cat','/sdcard/spool-window.xml');tree=owned_xml(raw);assert window()==win
 return tree,win

def dim():return tuple(map(int,re.findall(r'(\d+)x(\d+)',adb('shell','wm','size').decode())[-1]))
def bounds(n):
 b=list(map(int,re.findall(r'-?\d+',n.get('bounds',''))));assert len(b)==4
 x1,y1,x2,y2=b;w,h=dim();assert 0<=x1<x2<=w and 0<=y1<y2<=h,('Clipped target',b)
 return tuple(b)
def nodes(tree,ref):
 def match(n):
  v=value(ref)
  return v==n.get('content-desc') if ref[0]=='description' else (v==n.get('text') if ref[0]=='text' else v in (n.get('text'),n.get('content-desc')))
 ns=[n for n in tree.iter('node') if n.get('package')==PKG and match(n) and n.get('enabled')=='true']
 if ref[0]=='quick':
  parents={c:p for p in tree.iter() for c in p};bound=[]
  required={res(k,'shared') for k in ['shelf_for_you','mood_chill','mood_focus','mood_party','show_all']}
  for n in ns:
   p=parents.get(n)
   for _ in range(6):
    if p is None:break
    allnodes=list(p.iter('node'));labels={v for q in allnodes for v in [q.get('text'),q.get('content-desc')]}
    if required<=labels and sum(q.get('clickable')=='true' for q in allnodes)==5:bound.append(n);break
    p=parents.get(p)
  ns=bound
 return ns
def identity(tree,refs):
 for ref in refs:
  ns=nodes(tree,ref);assert len(ns)==1,('Page identity not unique',ref,len(ns));bounds(ns[0])
def wait_page(*refs):
 global PAGE
 end=time.monotonic()+15
 while True:
  try:tree,_=snapshot();identity(tree,refs);PAGE=refs;return
  except AssertionError:
   if time.monotonic()>end:raise
   time.sleep(.5)
def current(tree):assert PAGE;identity(tree,PAGE)
def control(tree,ref):
 current(tree);ns=nodes(tree,ref);parents={c:p for p in tree.iter() for c in p};targets=[]
 for label in ns:
  lb=bounds(label);n=label
  while n is not None and n.get('clickable')!='true':n=parents.get(n)
  assert n is not None and n.get('package')==PKG and n.get('enabled')=='true'
  cb=bounds(n);assert cb[0]<=lb[0] and cb[1]<=lb[1] and cb[2]>=lb[2] and cb[3]>=lb[3]
  # A giant container that includes unrelated actions is not a resolved target.
  desc=[q for q in n.iter('node') if q is not n and q.get('clickable')=='true'];assert not desc
  targets.append((n,label,cb,lb))
 assert len(targets)==1,('Ambiguous/disabled control',ref,len(targets));return targets[0]
def stable(ref,selected=False):
 a,wa=snapshot();na,la,ba,lba=control(a,ref)
 if selected:assert na.get('selected')=='true' or na.get('checked')=='true',('Exact option unselected',ref)
 sig=(wa,na.get('class'),na.get('resource-id'),na.get('text'),na.get('content-desc'),ba,lba,na.get('selected'),na.get('checked'))
 b,wb=snapshot();nb,lb,bb,lbb=control(b,ref);sig2=(wb,nb.get('class'),nb.get('resource-id'),nb.get('text'),nb.get('content-desc'),bb,lbb,nb.get('selected'),nb.get('checked'));assert sig==sig2,'Control moved/changed before input'
 return bb

def tap(ref):
 x1,y1,x2,y2=stable(ref);adb('shell','input','tap',(x1+x2)//2,(y1+y2)//2);time.sleep(.6)
def swipe(down=True):
 tree,_=snapshot();current(tree);w,h=dim();a,b=(.74,.33) if down else (.33,.74);adb('shell','input','swipe',w//2,int(h*a),w//2,int(h*b),350);time.sleep(.5)
def row(ref):
 for direction in [False,True]:
  for _ in range(12):
   tree,_=snapshot()
   if nodes(tree,ref):tap(ref);return
   swipe(direction)
 raise AssertionError('Unreachable control '+repr(ref))
def shot(name):
 tree,win=snapshot();current(tree);png=adb('exec-out','screencap','-p');assert png.startswith(b'\x89PNG\r\n\x1a\n');(OUT/(name+'.png')).write_bytes(png);(OUT/(name+'.xml')).write_bytes(ET.tostring(tree));SHOTS.append(dict(name=name,locale=LOCALE,page=[list(r) for r in PAGE],window=win,png_sha256=hashlib.sha256(png).hexdigest(),bytes=len(png)))

# Route predicate is explicit and independently checked by every control action.
GUARD=None
def current(tree):
 assert GUARD is not None, 'No route predicate'
 GUARD(tree)
def bind(guard):
 global GUARD
 tree,_=snapshot();guard(tree);GUARD=guard

def visible_unique(tree,ref):
 ns=nodes(tree,ref);assert len(ns)==1, ('Nonunique route anchor',ref,len(ns));bounds(ns[0]);return ns[0]
def anchors(*refs):
 def guard(tree):
  for ref in refs:visible_unique(tree,ref)
 return guard

def home_guard(tree):
 anchors(txt('settings'),txt('listening_history'),quick('shelf_for_you'),quick('show_all'))(tree)
def stable_middle_settings(tree):
 # Exact additional stable58 cluster captured at44969530326 first ambiguity.
 # Recognition only, never proof that any row is safe to tap or scroll.
 native_tabs(tree)
 labels=['Connected services','Listen together','Sources','On Wi-Fi','Downloads','Playback','Content Preferences']
 parents={c:p for p in tree.iter()for c in p};rows=[]
 for text_ in labels:
  label=visible_unique(tree,literal(text_));row=parents.get(label)
  assert row is not None and row.get('package')==PKG and row.get('enabled')=='true'and row.get('clickable')=='true'
  assert all(q is row or q.get('clickable')!='true'for q in row.iter('node')), 'Nested Settings cluster action'
  assert encloses(bounds(row),bounds(label))
  rows.append(row)
 assert len({id(q)for q in rows})==len(rows)
 assert all(bounds(a)[3]<=bounds(b)[1]for a,b in zip(rows,rows[1:])), 'Wrong Settings cluster order'
