 # Four prior captured states plus one exact structurally owned middle cluster.
 # No package-only/page-title-absent fallback, no actiongeometry bypass.
 anchors(desc('back'),desc('home'),desc('explore','shared'),desc('library','shared'),desc('search','shared'))(tree)
 states=[('Settings','Sources','On Wi-Fi'),('Sources','Downloads','Appearance','Local Music'),('Appearance','Performance','Local Music','Your data'),('Your data','Language','App updates')]
