def encloses(a,b):return a[0]<=b[0]<b[2]<=a[2] and a[1]<=b[1]<b[3]<=a[3]
def separate(a,b):return a[2]<=b[0] or b[2]<=a[0] or a[3]<=b[1] or b[3]<=a[1]
def native_tabs(tree):
 # The saved native bar has four owned clickable sibling tabs, not selected XML.
 parents={c:p for p in tree.iter() for c in p};items=[];container=None
 for ref in [desc('home'),desc('explore','shared'),desc('library','shared'),desc('search','shared')]:
  icon=visible_unique(tree,ref);tab=parents.get(icon)
  assert tab is not None and tab.get('package')==PKG and tab.get('enabled')=='true' and tab.get('clickable')=='true'
  assert all(q is tab or q.get('clickable')!='true' for q in tab.iter('node'))
  label=nodes(tab,('text',ref[1],ref[2]));assert len(label)==1
  tb=bounds(tab);assert encloses(tb,bounds(icon)) and encloses(tb,bounds(label[0]))
  row=parents.get(tab);assert row is not None and row.get('package')==PKG and row.get('enabled')=='true'
  if container is None:container=row
  assert row is container and tab not in items
  items.append(tab)
 assert [q for q in container if q.get('clickable')=='true']==items
 boxes=[bounds(q) for q in items];assert all(separate(a,b) for i,a in enumerate(boxes) for b in boxes[i+1:])
 assert all(boxes[i][2]<=boxes[i+1][0] for i in range(3))
 return container,boxes

def library_parts(tree):
 bar,tabs=native_tabs(tree);underbar=set(bar.iter('node'));parents={c:p for p in tree.iter() for c in p}
 # Library heading is unique OUTSIDE a verified tab bar. No first-match bypass.
 headings=[q for q in nodes(tree,text('library','shared')) if q not in underbar]
 assert len(headings)==1, 'Nonunique scoped Library heading'
 heading=headings[0];assert heading.get('class')=='android.widget.TextView' and heading.get('clickable')!='true'
 hb=bounds(heading);ancestor=parents.get(heading)
 while ancestor is not None:
  assert ancestor.get('clickable')!='true', 'Library heading inside an action'
  ancestor=parents.get(ancestor)
 rows=[];card=None
 for key,sub in [('downloads','downloaded_songs'),('local_music','audio_files_on_device')]:
  label=visible_unique(tree,txt(key));subtitle=visible_unique(tree,txt(sub));row=parents.get(label)
  assert row is not None and row is parents.get(subtitle)
  assert row.get('package')==PKG and row.get('enabled')=='true' and row.get('clickable')=='true'
  assert set(row.iter('node'))=={row,label,subtitle}, 'Unexpected Library row controls'
