def launch_named(name,normal=False):
 global RUNTIME_COMPONENT
 RUNTIME_COMPONENT=None
 assert re.fullmatch(r'[a-z0-9-]+',name)
 args=['shell','am','start','-W']+(['-a','android.intent.action.MAIN','-c','android.intent.category.LAUNCHER','-n',PKG+'/com.music.bitchord.LauncherSpool','-f','0x10200000'] if normal else ['-n',COMPONENT])
 path=OUT/(name+'.txt');path.write_text(json.dumps(dict(command=['adb']+args,launcher_style_alias=normal,direct_main_activity_cold_reopen=not normal,literal_icon_tap=False))+'\n')
 try:p=subprocess.run(['adb']+args,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=45)
 except subprocess.TimeoutExpired as e:
  with path.open('a') as f:f.write('TIMEOUT45s\n'+(e.stdout or b'').decode(errors='replace'))
  raise AssertionError('Launch timeout') from None
 except BaseException as e:
  with path.open('a') as f:f.write('COMMAND_FAILURE '+type(e).__name__)
  raise
 result=p.stdout.decode(errors='replace')
 with path.open('a') as f:f.write('returncode='+str(p.returncode)+'\n'+result)
 validate_launch_result(p.returncode,result,normal)
 # Bind exactly this phase's observed identity only after launch result passes.
 # Alias initial uses alias window/activity; direct cold uses target identity.
 RUNTIME_COMPONENT=ALIAS_COMPONENT if normal else COMPONENT
 for i in range(10):
  try:snapshot();return
  except AssertionError:
   if i==9:raise
   time.sleep(1)
 # No fallback, retry, monkey or alternate alias/component.
 # MainActivity in the returned result is allowed only as the verified alias target.

