    cl=[q for q in allnodes if q.get('package')==PKG and q.get('clickable')=='true' and q.get('enabled')=='true']
    present=required&labels
    if len(present)==4 and len(cl)==5:
     def sublabels(q):return {v for r in q.iter('node') for v in (r.get('text'),r.get('content-desc')) if v}
     # The clipped chip must carry NO label at all, and each of the other four
     # must carry one of the required labels; any other composition is unknown.
